    const gap = chartW / data.length * 0.3;

    // Y axis
    svg.appendChild(createSVGElement('line', { x1: margin.left, y1: margin.top, x2: margin.left, y2: height - margin.bottom, stroke: '#e0e0e0', 'stroke-width': 1 }));
    // X axis
    svg.appendChild(createSVGElement('line', { x1: margin.left, y1: height - margin.bottom, x2: width - margin.right, y2: height - margin.bottom, stroke: '#e0e0e0', 'stroke-width': 1 }));

    // Y ticks
    for (let i = 0; i <= 5; i++) {
      const y = height - margin.bottom - (chartH * i / 5);
      const val = (maxVal * i / 5).toFixed(options.yDecimals || 0);
