      const barH = (d[valueKey] / maxVal) * chartH;
      const y = height - margin.bottom - barH;

      const rect = createSVGElement('rect', { x, y, width: barW, height: barH, fill: barColor, rx: 3 });
      svg.appendChild(rect);

      // Label
      const label = createSVGElement('text', { x: x + barW/2, y: height - margin.bottom + 18, 'text-anchor': 'middle', 'font-size': 11, fill: '#2c3e50' });
