  // Y ticks
  for (let i = 0; i <= 5; i++) {
    const y = height - margin.bottom - (chartH * i / 5);
    const val = (minVal + (maxVal - minVal) * i / 5).toFixed(options.yDecimals || 0);
    svg.appendChild(createSVGElement('text', { x: margin.left - 8, y: y + 4, 'text-anchor': 'end', 'font-size': 11, fill: '#7f8c8d' })).textContent = val;
    svg.appendChild(createSVGElement('line', { x1: margin.left, y1: y, x2: width - margin.right, y2: y, stroke: '#f0f0f0', 'stroke-width': 1 }));
