function drawHeatmap(svgId, data, options = {}) {
  const svg = document.getElementById(svgId);
  if (!svg) return;
  const { width = 900, height = 340, minVal = 0, maxVal = 100 } = options;
  svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
  svg.innerHTML = '';

  const margin = { top: 40, right: 120, bottom: 50, left: 80 };
  const chartW = width - margin.left - margin.right;
  const chartH = height - margin.top - margin.bottom;

  const rows = Object.keys(data);
  const cols = Object.keys(data[rows[0]]);
  const cellW = chartW / cols.length;
  const cellH = chartH / rows.length;

  // Color scale
  function colorScale(v) {
    const t = Math.max(0, Math.min(1, (v - minVal) / (maxVal - minVal)));
    // Blue to red
    const r = Math.round(26 + (192 - 26) * t);
    const g = Math.round(95 + (57 - 95) * t);
    const b = Math.round(122 + (43 - 122) * t);
    return `rgb(${r},${g},${b})`;
  }

  // Cells
  rows.forEach((row, ri) => {
    cols.forEach((col, ci) => {
      const val = data[row][col];
      const x = margin.left + ci * cellW;
      const y = margin.top + ri * cellH;
      const rect = createSVGElement('rect', { x, y, width: cellW - 2, height: cellH - 2, fill: colorScale(val), rx: 2 });
      svg.appendChild(rect);

      // Value text
      const text = createSVGElement('text', { x: x + cellW/2, y: y + cellH/2 + 4, 'text-anchor': 'middle', 'font-size': 10, fill: (val > (maxVal + minVal)/2) ? 'white' : '#2c3e50', 'font-weight': '500' });
